/**
 * Одноразовый импорт черновиков интро.
 *
 * Заполняет только пустые интро, не включает страницы и не перезаписывает
 * правки владельца. Если опция страниц ещё пуста, повторяет попытку позже.
 */
function sad_znaniy_programmatic_intros_install() {
	if ( '1' === get_option( 'sad_znaniy_pg_intros_version' ) ) {
		return;
	}

	$pages = get_option( 'sad_znaniy_programmatic_pages', array() );
	if ( empty( $pages ) ) {
		return;
	}

	$intros  = sad_znaniy_programmatic_intros();
	$changed = false;

	foreach ( $intros as $key => $intro ) {
		if ( ! isset( $pages[ $key ] ) || '' !== trim( (string) $pages[ $key ]['intro'] ) ) {
			continue;
		}
		$pages[ $key ]['intro']   = $intro;
		$pages[ $key ]['enabled'] = 0;
		$changed                  = true;
	}

	if ( $changed ) {
		update_option( 'sad_znaniy_programmatic_pages', $pages, false );
	}

	update_option( 'sad_znaniy_pg_intros_version', '1', false );
}
add_action( 'init', 'sad_znaniy_programmatic_intros_install', 26 );
